import { Request, Response } from 'express';
import { CancelOrderUseCase } from '../../../application/use-cases/CancelOrderUseCase';
import { DeliverOrderUseCase } from '../../../application/use-cases/DeliverOrderUseCase';
import { GetOrderUseCase } from '../../../application/use-cases/GetOrderUseCase';
import { ListOrdersUseCase } from '../../../application/use-cases/ListOrdersUseCase';
import { PackOrderUseCase } from '../../../application/use-cases/PackOrderUseCase';
import { PayOrderUseCase } from '../../../application/use-cases/PayOrderUseCase';
import { PlaceOrderUseCase } from '../../../application/use-cases/PlaceOrderUseCase';
import { ShipOrderUseCase } from '../../../application/use-cases/ShipOrderUseCase';
import { parsePlaceOrderBody, parseStateQuery } from '../requestParsing';

export interface OrderUseCases {
  readonly placeOrder: PlaceOrderUseCase;
  readonly getOrder: GetOrderUseCase;
  readonly listOrders: ListOrdersUseCase;
  readonly payOrder: PayOrderUseCase;
  readonly packOrder: PackOrderUseCase;
  readonly shipOrder: ShipOrderUseCase;
  readonly deliverOrder: DeliverOrderUseCase;
  readonly cancelOrder: CancelOrderUseCase;
}

type IdParams = { id: string };

/** Translates HTTP requests into order use case calls. */
export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  place = (req: Request, res: Response): void => {
    const order = this.useCases.placeOrder.execute(parsePlaceOrderBody(req.body));
    res.status(201).location(`/orders/${order.id}`).json(order);
  };

  list = (req: Request, res: Response): void => {
    res.json(this.useCases.listOrders.execute(parseStateQuery(req.query.state)));
  };

  get = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.getOrder.execute(req.params.id));
  };

  pay = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.payOrder.execute(req.params.id));
  };

  pack = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.packOrder.execute(req.params.id));
  };

  ship = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.shipOrder.execute(req.params.id));
  };

  deliver = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.deliverOrder.execute(req.params.id));
  };

  cancel = (req: Request<IdParams>, res: Response): void => {
    res.json(this.useCases.cancelOrder.execute(req.params.id));
  };
}

