import { Request, Response } from 'express';
import { GetProductStockUseCase } from '../../../application/use-cases/GetProductStockUseCase';
import { ListProductStockUseCase } from '../../../application/use-cases/ListProductStockUseCase';

/** Exposes product stock levels to staff. */
export class StockController {
  constructor(
    private readonly listProductStock: ListProductStockUseCase,
    private readonly getProductStock: GetProductStockUseCase,
  ) {}

  list = (_req: Request, res: Response): void => {
    res.json(this.listProductStock.execute());
  };

  get = (req: Request<{ id: string }>, res: Response): void => {
    res.json(this.getProductStock.execute(req.params.id));
  };
}

